/**
 * viewer.js — series strips + shared fullscreen image viewer
 *
 * portfolioStrip.build(series, opts)  → horizontal scroll-snap strip of images
 * portfolioViewer.open(series, index) → fullscreen viewer stepping through one series
 *
 * series = { title, href, images: [src, ...] }
 * Used by gallery.html (gallery.js) and work pages (work-detail.js).
 * Image sizes come from js/imageSizes.parts.js (generated by npm run build-data).
 */
(function () {
  'use strict';

  function resolveSrc(src) {
    var utils = window.portfolioUtils || {};
    return typeof utils.resolveAssetSrc === 'function' ? utils.resolveAssetSrc(src) : src;
  }

  var SWIPE_MIN_PX = 40;

  function sizeFor(src) {
    var sizes = window.__IMAGE_SIZES__ || {};
    var key = String(src || '').replace(/^\.?\//, '');
    return sizes[key] || null;
  }

  function imageLabel(series, index) {
    var title = series.title || 'Untitled';
    var total = (series.images || []).length;
    return total > 1 ? title + ' — image ' + (index + 1) + ' of ' + total : title;
  }

  /* ---------- Strip ---------- */

  function buildStrip(series, opts) {
    opts = opts || {};
    var images = series.images || [];
    var eagerCount = typeof opts.eagerCount === 'number' ? opts.eagerCount : 2;

    var strip = document.createElement('div');
    strip.className = 'media-strip' + (opts.variant ? ' media-strip--' + opts.variant : '');
    strip.setAttribute('role', 'region');
    strip.setAttribute('aria-label', (series.title || 'Untitled') + ' images');
    strip.tabIndex = 0;

    var track = document.createElement('ul');
    track.className = 'media-strip__track';

    images.forEach(function (src, index) {
      var li = document.createElement('li');
      li.className = 'media-strip__item';

      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'media-strip__btn';
      btn.setAttribute('aria-label', 'Open ' + imageLabel(series, index) + ' fullscreen');

      var img = document.createElement('img');
      img.alt = imageLabel(series, index);
      var dims = sizeFor(src);
      if (dims) {
        img.width = dims[0];
        img.height = dims[1];
      }
      img.loading = index < eagerCount ? 'eager' : 'lazy';
      img.decoding = 'async';
      img.src = resolveSrc(src);

      btn.appendChild(img);
      btn.addEventListener('click', function () {
        openViewer(series, index);
      });
      li.appendChild(btn);
      track.appendChild(li);
    });

    strip.appendChild(track);
    return strip;
  }

  /** Wire click handlers onto a strip baked at build time (work pages). */
  function hydrateStrip(strip, series) {
    if (!strip) return;
    strip.querySelectorAll('.media-strip__btn').forEach(function (btn, index) {
      btn.addEventListener('click', function () {
        openViewer(series, index);
      });
    });
  }

  /* ---------- Viewer ---------- */

  var viewerEl, imgEl, captionEl, counterEl, closeBtn, prevBtn, nextBtn, frameEl;
  var state = null;
  var lastFocused = null;
  var closeTimer = null;

  function makeButton(className, label, text) {
    var b = document.createElement('button');
    b.type = 'button';
    b.className = className;
    b.setAttribute('aria-label', label);
    b.textContent = text;
    return b;
  }

  function buildViewer() {
    viewerEl = document.createElement('div');
    viewerEl.className = 'viewer';
    viewerEl.setAttribute('role', 'dialog');
    viewerEl.setAttribute('aria-modal', 'true');
    viewerEl.setAttribute('aria-label', 'Image viewer');
    viewerEl.hidden = true;

    var backdrop = makeButton('viewer__backdrop', 'Close viewer', '');
    backdrop.tabIndex = -1;
    closeBtn = makeButton('viewer__close', 'Close viewer', '×');
    prevBtn = makeButton('viewer__nav viewer__nav--prev', 'Previous image', '‹');
    nextBtn = makeButton('viewer__nav viewer__nav--next', 'Next image', '›');

    frameEl = document.createElement('div');
    frameEl.className = 'viewer__frame';
    imgEl = document.createElement('img');
    imgEl.className = 'viewer__img';
    imgEl.alt = '';
    frameEl.appendChild(imgEl);

    captionEl = document.createElement('p');
    captionEl.className = 'viewer__caption';
    captionEl.setAttribute('aria-live', 'polite');

    viewerEl.appendChild(backdrop);
    viewerEl.appendChild(closeBtn);
    viewerEl.appendChild(prevBtn);
    viewerEl.appendChild(nextBtn);
    viewerEl.appendChild(frameEl);
    viewerEl.appendChild(captionEl);
    document.body.appendChild(viewerEl);

    backdrop.addEventListener('click', closeViewer);
    closeBtn.addEventListener('click', closeViewer);
    prevBtn.addEventListener('click', function () { step(-1); });
    nextBtn.addEventListener('click', function () { step(1); });
    document.addEventListener('keydown', onKeydown);
    bindSwipe(frameEl);
  }

  function bindSwipe(el) {
    var startX = null;
    var startY = null;
    el.addEventListener('pointerdown', function (e) {
      startX = e.clientX;
      startY = e.clientY;
    });
    el.addEventListener('pointerup', function (e) {
      if (startX == null) return;
      var dx = e.clientX - startX;
      var dy = e.clientY - startY;
      startX = startY = null;
      if (Math.abs(dx) >= SWIPE_MIN_PX && Math.abs(dx) > Math.abs(dy)) step(dx < 0 ? 1 : -1);
    });
    el.addEventListener('pointercancel', function () { startX = startY = null; });
  }

  function preload(src) {
    if (!src) return;
    var pre = new Image();
    pre.decoding = 'async';
    pre.src = resolveSrc(src);
  }

  function render() {
    var images = state.series.images;
    var total = images.length;
    var src = images[state.index];
    var dims = sizeFor(src);

    imgEl.removeAttribute('width');
    imgEl.removeAttribute('height');
    if (dims) {
      imgEl.width = dims[0];
      imgEl.height = dims[1];
    }
    imgEl.src = resolveSrc(src);
    imgEl.alt = imageLabel(state.series, state.index);

    captionEl.innerHTML = '';
    var title = state.series.title || 'Untitled';
    if (state.series.href) {
      var link = document.createElement('a');
      link.href = state.series.href;
      link.textContent = title;
      captionEl.appendChild(link);
    } else {
      captionEl.appendChild(document.createTextNode(title));
    }
    captionEl.appendChild(document.createTextNode(' · ' + (state.index + 1) + ' / ' + total));

    var multi = total > 1;
    prevBtn.hidden = !multi;
    nextBtn.hidden = !multi;

    if (multi) {
      preload(images[(state.index + 1) % total]);
      preload(images[(state.index - 1 + total) % total]);
    }
  }

  function openViewer(series, index) {
    if (!series || !series.images || !series.images.length) return;
    if (!viewerEl) buildViewer();
    if (closeTimer) {
      window.clearTimeout(closeTimer);
      closeTimer = null;
    }

    if (!state) lastFocused = document.activeElement;
    state = {
      series: series,
      index: Math.max(0, Math.min(index || 0, series.images.length - 1))
    };
    render();

    viewerEl.hidden = false;
    document.body.classList.add('viewer-open');
    requestAnimationFrame(function () {
      viewerEl.classList.add('is-open');
      /* Focus once visible — visibility:hidden elements can't take focus */
      closeBtn.focus();
    });
  }

  function closeViewer() {
    if (!viewerEl || viewerEl.hidden || !state) return;
    viewerEl.classList.remove('is-open');
    document.body.classList.remove('viewer-open');
    state = null;

    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    closeTimer = window.setTimeout(function () {
      closeTimer = null;
      viewerEl.hidden = true;
      imgEl.removeAttribute('src');
      if (lastFocused) {
        try { lastFocused.focus(); } catch (e) { /* noop */ }
        lastFocused = null;
      }
    }, reduce ? 0 : 320);
  }

  function step(delta) {
    if (!state) return;
    var total = state.series.images.length;
    if (total < 2) return;
    state.index = (state.index + delta + total) % total;
    render();
  }

  function trapFocus(e) {
    var focusable = Array.prototype.filter.call(
      viewerEl.querySelectorAll('button, [href]'),
      function (el) { return !el.hidden && el.tabIndex !== -1; }
    );
    if (!focusable.length) return;
    var first = focusable[0];
    var last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  function onKeydown(e) {
    if (!state) return;
    if (e.key === 'Escape') { e.preventDefault(); closeViewer(); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); step(-1); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); step(1); }
    else if (e.key === 'Tab') trapFocus(e);
  }

  window.portfolioStrip = {
    build: buildStrip,
    hydrate: hydrateStrip,
    sizeFor: sizeFor
  };

  window.portfolioViewer = {
    open: openViewer,
    close: closeViewer
  };
})();
